using System.Text;
namespace QualifyAI.Api;
public static class AutonomousAcquisitionDashboardEndpoints{public static IEndpointRouteBuilder MapAutonomousAcquisitionDashboard(this IEndpointRouteBuilder app){app.MapGet("/autonomous-acquisition",()=>Results.Content(Html(),"text/html; charset=utf-8"));return app;}static string Html()=>"""<!doctype html><html><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>Autonomous Acquisition</title><style>body{font-family:Inter,Arial;margin:0;background:#0b1020;color:#e8eefc}.wrap{max-width:1200px;margin:auto;padding:32px}.card{background:#151d33;border:1px solid #26304d;border-radius:14px;padding:18px;margin-top:18px}.muted{color:#9ca9c9}button{background:#4f7cff;color:#fff;border:0;border-radius:8px;padding:9px 12px;cursor:pointer;margin:2px}.danger{background:#b84a5a}.row{display:flex;gap:8px;flex-wrap:wrap}.row>*{flex:1;min-width:160px}input,select,textarea{padding:10px;background:#0f1628;color:#fff;border:1px solid #34405f;border-radius:8px;width:100%;box-sizing:border-box}table{width:100%;border-collapse:collapse}th,td{padding:9px;border-bottom:1px solid #26304d;text-align:left}.pill{padding:4px 8px;border-radius:99px;background:#26304d}.hidden{display:none}</style></head><body><div class='wrap'><h1>Autonomous Acquisition Agent</h1><div class='card'><div class='row'><input id='tenant' placeholder='Tenant ID'><button onclick='load()'>Load</button><button onclick='showCreate()'>Create Agent</button></div></div><div id='editor' class='card hidden'><h2 id='formTitle'>Create Agent</h2><div class='row'><input id='name' placeholder='Agent name'><select id='template'></select><input id='industry' placeholder='Industry'></div><div class='row'><input id='region' placeholder='Region'><input id='countries' placeholder='Countries, comma separated'><input id='threshold' type='number' value='90'></div><div class='row'><input id='dailyDiscovery' type='number' value='50'><input id='dailyEmail' type='number' value='20'><input id='runTime' type='time' value='08:00'></div><textarea id='icp' placeholder='ICP notes'></textarea><button onclick='saveAgent()'>Save Agent</button><button onclick='cancelEdit()'>Cancel</button></div><div class='card'><h2>Agents</h2><table><thead><tr><th>Name</th><th>Template</th><th>Status</th><th>Score</th><th>Actions</th></tr></thead><tbody id='agents'></tbody></table></div></div><script>let editing=null;const base=()=>'/api/autonomous-acquisition/tenants/'+tenant.value+'/agents';async function load(){if(!tenant.value)return;let ts=await fetch('/api/autonomous-acquisition/templates').then(r=>r.json());template.innerHTML=ts.map(x=>`<option value='${x.code}'>${x.name}</option>`).join('');let a=await fetch(base()).then(r=>r.json());agents.innerHTML=a.map(x=>`<tr><td>${x.name}</td><td>${x.templateCode}</td><td><span class='pill'>${x.status}</span></td><td>${x.minimumScore}</td><td><button onclick='editAgent("${x.id}")'>Edit</button><button onclick='action("${x.id}","activate")'>Activate</button><button onclick='action("${x.id}","pause")'>Pause</button><button class='danger' onclick='action("${x.id}","stop")'>Stop</button><button onclick='action("${x.id}","run")'>Run Now</button></td></tr>`).join('');window.current=a;}async function action(id,a){let r=await fetch(base()+'/'+id+'/'+a,{method:'POST'});if(!r.ok)alert(await r.text());await load();}function showCreate(){editing=null;formTitle.textContent='Create Agent';editor.classList.remove('hidden');}function cancelEdit(){editor.classList.add('hidden');}function editAgent(id){editing=current.find(x=>x.id===id);let x=editing;name.value=x.name||'';template.value=x.templateCode||'';industry.value=x.industry||'';region.value=x.region||'';countries.value=x.countriesJson||'';threshold.value=x.minimumScore||90;dailyDiscovery.value=x.dailyDiscoveryLimit||50;dailyEmail.value=x.dailyEmailLimit||20;runTime.value=x.runTimeUtc||'08:00';icp.value=x.icpNotes||'';editor.classList.remove('hidden');}async function saveAgent(){let b={name:name.value,templateCode:template.value,industry:industry.value,region:region.value,countriesJson:countries.value,minimumScore:+threshold.value,dailyDiscoveryLimit:+dailyDiscovery.value,dailyEmailLimit:+dailyEmail.value,runTimeUtc:runTime.value,icpNotes:icp.value};let u=base()+(editing?'/'+editing.id:'');let r=await fetch(u,{method:editing?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(b)});if(!r.ok){alert(await r.text());return;}cancelEdit();load();}</script></body></html>""";}
